"""Render the frozen counterfactual result, with its measurement limits."""
from pathlib import Path
from html import escape
import json

HERE = Path(__file__).resolve().parent
def read(name):
    return json.loads((HERE / name).read_text())

baseline = read('baseline-test.json')['metrics']
candidate = read('final-fixed-test.json')['metrics']
real_baseline = read('baseline-real-test.json')['metrics']
real_candidate = read('final-real-test.json')['metrics']
tokens = read('heldout-tokens.json')
ledger = [json.loads(line) for line in (HERE / 'climb.jsonl').read_text().splitlines()]
source = read('source-map.json')
lock = read('final-lock.json')
reduction = 1 - candidate['text_tokens'] / baseline['text_tokens']

def percent(value):
    return f'{value:.1%}' if value is not None else 'undefined'

def metrics_row(label, before, after):
    return f'''<tr><th scope="row">{escape(label)}</th>
    <td>{percent(before['precision'])}<small>{before['jit_tp']}/{before['jit_tp'] + before['jit_fp']} relevant JIT deliveries</small></td>
    <td>{percent(after['precision'])}<small>{after['jit_tp']}/{after['jit_tp'] + after['jit_fp']} relevant JIT deliveries</small></td>
    <td>{percent(before['availability'])}<small>{before['availability_hits']}/{before['applications']} applicable rules</small></td>
    <td>{percent(after['availability'])}<small>{after['availability_hits']}/{after['applications']} applicable rules</small></td></tr>'''

round_rows = ''
for row in ledger:
    metrics = row.get('train', {})
    p = row.get('train_precision', metrics.get('precision'))
    a = row.get('train_availability', metrics.get('availability'))
    t = row.get('train_tokens', metrics.get('text_tokens'))
    round_rows += '<tr><th scope="row">' + escape(str(row.get('candidate', 'baseline'))) + '</th><td>' + percent(p) + '</td><td>' + percent(a) + '</td><td>' + (f'{t:,.0f}' if t is not None else '—') + '</td><td>' + escape(str(row.get('verdict', row.get('decision', 'recorded')))) + '</td><td>' + escape(str(row.get('change', ''))) + '</td></tr>'

def bars():
    rows = [('Fixed precision, today', baseline['precision']), ('Fixed precision, candidate', candidate['precision']),
            ('Fixed availability, today', baseline['availability']), ('Fixed availability, candidate', candidate['availability'])]
    content = ''
    for i, (name, value) in enumerate(rows):
        y = 35 + i * 46
        color = '#ff8a3d' if 'candidate' in name else '#718aa9'
        content += f'<text x="8" y="{y+14}" fill="#d6e1ee" font-size="13">{name}</text><rect x="230" y="{y}" width="{value*330:.1f}" height="23" rx="5" fill="{color}"/><text x="575" y="{y+16}" fill="#e8eef5" font-size="14">{percent(value)}</text>'
    return '<svg role="img" aria-label="Fixed held-out precision improves from 27.1 to 82.3 percent; availability improves from 81.3 to 82.4 percent" viewBox="0 0 655 230">' + content + '</svg>'

html = f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Rule delivery precision · final checkpoint</title><style>
:root{{color-scheme:dark;font-family:system-ui,sans-serif;background:#07111e;color:#e6edf6}}*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(ellipse at top right,#18304b,transparent 55%),#07111e}}main{{max-width:1120px;margin:auto;padding:42px 24px 70px}}a{{color:#ff9b57}}h1{{font-size:clamp(30px,5vw,54px);line-height:1.05;margin:12px 0 20px}}h2{{margin-top:36px}}p{{max-width:900px;line-height:1.65}}.kicker{{color:#ff9b57;letter-spacing:.12em;font-size:12px;text-transform:uppercase}}.lead{{font-size:20px}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin:30px 0}}.card,section,details{{background:#0b1b2dd9;border:1px solid #27425f;border-radius:14px;padding:22px}}.card strong{{display:block;font-size:38px;color:#ff9b57}}small{{display:block;font-size:12px;color:#acbfd2;margin-top:6px}}.table-wrap{{overflow:auto}}table{{border-collapse:collapse;width:100%;font-size:14px}}th,td{{padding:14px 12px;border-bottom:1px solid #27425f;text-align:left;vertical-align:top}}thead{{color:#ffb07a}}summary{{cursor:pointer;font-weight:600}}details{{margin-top:20px}}code{{font-size:12px;color:#c9d9eb;overflow-wrap:anywhere}}.shape{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.shape div{{padding:16px;border:1px solid #355472;border-radius:10px}}svg{{display:block;width:100%;max-width:850px}}.notice{{border-left:3px solid #ff8a3d;padding:8px 18px;background:#14263a}}button{{background:#173552;border:1px solid #66839f;color:white;padding:10px 15px;border-radius:8px;cursor:pointer}}@media(max-width:650px){{main{{padding:24px 16px}}.shape{{grid-template-columns:1fr}}th,td{{min-width:140px}}}}@media(prefers-reduced-motion:no-preference){{details[open]{{animation:appear .16s ease-out}}@keyframes appear{{from{{opacity:.6;transform:translateY(3px)}}to{{opacity:1;transform:none}}}}}}
</style><main><div class="kicker">CARR · measured 2026-10-05 · one frozen candidate · zero model calls</div>
<h1>The selected rules now apply.</h1><p class="lead">The frozen candidate meets the requested held-out targets: <b>82.3% precision</b> with <b>82.4% availability</b> on the fixed 72 cases. Today's comparison is 27.1% and 81.3%.</p>
<p>It replaces topical overmatching with action conditions and TRAIN-only per-rule accept/reject gates. The shipped hook records this proposal beside today's delivered receipt. It returns today's output unchanged; shadow is disabled by default.</p>
<div class="cards"><div class="card"><strong>{percent(candidate['precision'])}</strong>Fixed held-out precision<small>79 relevant /96 new deliveries;17 irrelevant</small></div><div class="card"><strong>{percent(candidate['availability'])}</strong>Fixed held-out availability<small>591/717 applicable statements; floor 583/717</small></div><div class="card"><strong>{percent(reduction)}</strong>Lower estimated statement tokens<small>121,337.5→38,471.25; each fixed case a session proxy</small></div></div>
<section><h2 style="margin-top:0">Before and after on held-out cases</h2><div class="table-wrap" tabindex="0"><table><thead><tr><th>Held-out set</th><th>Today's precision</th><th>Candidate precision</th><th>Today's availability</th><th>Candidate availability</th></tr></thead><tbody>{metrics_row('Fixed 72 whole turns', baseline, candidate)}{metrics_row('Real 40 visible events /29 sessions',real_baseline,real_candidate)}</tbody></table></div>{bars()}<p class="notice">The real sample is an engineering/governance check, not brokerage-wide evidence. It contains 22 candidate JIT positives, all for the retrieval-first rule. Four partner-prose rules are assumed universal; context-dependent conditions are disputed. Its 100% precision has limited coverage.</p></section>
<h2>Why the noise fell</h2><div class="shape"><div><b>1. Read the action</b><small>Tool, executable command head, record verb, written path and expressed intent.</small></div><div><b>2. Apply the condition</b><small>Conjunctions and negative predicates reject quoted commands, internal copy and routine staffing.</small></div><div><b>3. Apply the TRAIN gate</b><small>17 supported rule IDs retained after empirical relevance cutoff 0.50. This is not calibrated probability.</small></div><div><b>4. Observe separately</b><small>Full-text IDs, overflow pointers, candidate IDs and once-per-session proposals stay distinct.</small></div></div>
<p>Generic Agent routes caused much of the irrelevant delivery: Copilot selection, red-team composition, architecture councils and prospect-copy lint were delivered to routine workers. Prompt triggers accepted author-time probabilities from 0.50. Route and compiled selections were unioned, preserving noise from both paths. Actual drift observation injects nothing; hypothetical whole-pack expansion is especially noisy.</p>
<p>A separate 30-pair gold audit accepts 11 missing-positive proposals. If admitted, today's precision would be 31.3% instead of 27.1%. The frozen gold was not changed, and those test audit examples were not used for tuning. <a href="study.html">Read the diagnosis and source research</a>; <a href="archaeology.md">read the 20 earlier proposal families</a>.</p>
<details><summary>TRAIN hill climb and stopping rule</summary><p>168 original TRAIN cases plus 121 eligible real TRAIN events. Nine calibration candidates followed the initial predicate experiment. Winner:179 TP/41 FP,81.36% precision and 1392/1690,82.37% availability. The final three alternatives added no retained gain.</p><p>The point-optimal rule subset achieved 83.51% TRAIN precision at 81.361% availability, only 0.05 percentage points above the floor. It was rejected before test for that fragile coverage margin. Minimum-positive support lost precision; removing action additions failed availability. This is a bounded search result, not a proof of a global ceiling. No local statistical classifier or embedding model was fitted; those remain studied alternatives.</p><div class="table-wrap" tabindex="0"><table><thead><tr><th>Candidate</th><th>TRAIN precision</th><th>TRAIN availability</th><th>Token estimate</th><th>Decision</th><th>Change</th></tr></thead><tbody>{round_rows}</tbody></table></div><p><a href="climb.jsonl">Machine-readable iteration ledger</a> · Jev calls 0 of 1500; no paid Claude API. Original 240 fixture and 168/72 membership remain unchanged. Candidate source/config were checkpointed before held-out scoring. Each final candidate split was scored once; no post-test tuning.</p></details>
<details><summary>Token accounting and session dedupe</summary><p>Statement characters/4 excludes receipt overhead and boot cost. Fixed-case union estimates are 121,337.5 before and 38,471.25 after. Fixed cases stand in for sessions; they do not measure complete session context.</p><p>On sampled real held-out events, once-per-session estimates are{tokens['real_baseline']['once_per_session_full_text_estimate']:,.1f} before and{tokens['real_candidate']['once_per_session_full_text_estimate']:,.1f} after across 29 session groups ({tokens['real_baseline']['per_session_once_estimate']:.1f}→{tokens['real_candidate']['per_session_once_estimate']:.1f} tokens/group). Earlier/later unobserved events are absent. Existing time/tool dedupe means per-event totals are an upper bound, not observed billing.</p><p>Shadow's once-per-rule/session ledger records proposals only. It does not suppress actual delivery or claim text survived compaction. A future live selector must dedupe by verified context generation and statement revision, and fetch missing full text before the binding action. One-line pointers are not full-text availability.</p></details>
<details><summary>Shadow, health response and verification</summary><p><code>CARR_RULEPRECISION_SHADOW=1</code> enables local comparisons. No rule text, prompt, tool arguments, client paths or exception text is logged. Input/session hashes, current selector+config+parser digest, selected IDs and full-text/pointer receipt IDs are logged. Invalid observation data returns today's original output.</p><p><code>health --section ruleprecision</code> is read-only by default. Independently audited current-generation labels plus verified boot evidence are required. Fewer than 20 fresh samples, malformed data or missing evidence gives UNKNOWN. The row prints thresholds, the deduplicated rule-delivery-precision loop, owner Claude orchestration lane, remediation and auto-clear test inline. Explicit <code>CARR_RULEPRECISION_HEALTH_APPLY=1</code> enables the implemented response; no such production action was run for this task.</p><p>RED-first tests cover selection, unchanged output, privacy, concurrency, stale-generation labels, malformed data, failed write acknowledgments and the bound response. Both required design/debt passes were applied; independent review findings were fixed. The hook's gate baseline is re-blessed with its source change. Canonical rule-delivery receipt is regression evidence for unchanged live delivery, with its historical reuse disclosed; these new counterfactual metrics are separate.</p></details>
<details><summary>Evidence, limits and reproduction</summary><p>Availability is by-turn full-text selection under successful-fetch assumptions. The report does not prove hook invocation on every host, cap transport, obedience, pre-action arrival or compaction retention. Gold spans current 199 active rules; only 82 had a positive in the original test. Live precision remains unmeasured.</p><p>Real inputs were copied read-only from recent top-level local sessions, stripped through an explicit whitelist, then session-split before selection/labeling:73 TRAIN sessions and 29 held-out. 163 events overall; two context-poor human fragments excluded from TRAIN headlines. Source hashes and rationales remain in <a href="real-turns/protocol.html">the real-turn protocol</a> and <a href="real-turns/manifest.json">manifest</a>.</p><p><a href="final-lock.json">Pre-test lock</a> · <a href="final-fixed-test.json">Fixed result</a> · <a href="final-real-test.json">Real result</a> · <a href="heldout-tokens.json">Tokens</a> · <a href="gold-audit.json">Gold audit</a> · <a href="calibration-reproduced.json">Reproduced TRAIN calibration</a> · <a href="independent-review.json">Independent review</a>.</p><p>Reproduce TRAIN with <code>python3 tools/ruleprecision-calibrate.py --cases out/orch/ruleprecision/train.jsonl --real-train out/orch/ruleprecision/real-train.jsonl --corpus out/orch/ruleprecision/real-turns/rule-texts.json --contract out/orch/ruleprecision/baseline-contract.json --config out/orch/ruleprecision/candidate-config.json --out &lt;new-output&gt;</code>. Do not rerun the final split for selection.</p><p>Base revision<code>{escape(lock['source_revision'])}</code>; source/config/fixtures are pinned in the lock. This PR is not merged and does not change live delivery.</p></details>
<p><button type="button" id="expand">Expand all evidence</button></p></main><script>document.getElementById('expand').addEventListener('click',function(){{const open=this.textContent.startsWith('Expand');document.querySelectorAll('details').forEach(d=>d.open=open);this.textContent=open?'Collapse evidence':'Expand all evidence';}});</script></html>'''
(HERE / 'final.html').write_text(html)
print('Rendered final.html from frozen results.')
